	};
	{
		reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\Explorer" /v DisableSearchBoxSuggestions /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced\TaskbarDeveloperSettings" /v TaskbarEndTask /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Control Panel\Accessibility\StickyKeys" /v Flags /t REG_SZ /d 10 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ShowInfoTip" /d 0 /t REG_DWORD /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce" /v "UnattendedSetup" /t REG_SZ /d "powershell.exe -WindowStyle \""Normal\"" -ExecutionPolicy \""Unrestricted\"" -NoProfile -File \""C:\Windows\Setup\Scripts\UserOnce.ps1\""" /f;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to modify the default user’’s registry hive. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\DefaultUser.log";

$scripts = @(
	{
		@(
			Get-ChildItem -LiteralPath 'C:\' -Force;
			Get-ChildItem -LiteralPath 'C:\Users' -Force;
			Get-ChildItem -LiteralPath 'C:\Users\Default' -Force -Recurse -Depth 2;
			Get-ChildItem -LiteralPath 'C:\Users\Public' -Force -Recurse -Depth 2;
			Get-ChildItem -LiteralPath 'C:\ProgramData' -Force;
		) | Where-Object -FilterScript {
			$_.Attributes.HasFlag( [System.IO.FileAttributes]::ReparsePoint );
		} | Remove-Item -Force -Recurse -Verbose;
	};
	{
		Disable-ComputerRestore -Drive 'C:\';
	};
	{
		cmd.exe /c "rmdir C:\Windows.old";
	};
	{
		Remove-Item -LiteralPath @(
		  'C:\Windows\Panther\unattend.xml';
		  'C:\Windows\Panther\unattend-original.xml';
		  'C:\Windows\Setup\Scripts\Wifi.xml';
		) -Force -ErrorAction 'SilentlyContinue' -Verbose;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to finalize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\FirstLogon.log";

$repoUrl = 'https://github.com/Viktor-V/windows-setup/archive/refs/heads/main.zip';
$stageDir = Join-Path $env:USERPROFILE 'DevSetup';
$zipPath = Join-Path $stageDir 'windows-setup.zip';
$extractDir = Join-Path $stageDir 'extracted';
$logFile = Join-Path $stageDir 'download.log';

function Write-Log {
    param([string]$Message)
    $timestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss';
    $line = "[$timestamp] $Message";
    Write-Host $line;
    Add-Content -LiteralPath $logFile -Value $line -ErrorAction 'SilentlyContinue';
}

New-Item -Path $stageDir -ItemType Directory -Force | Out-Null;

Write-Host '';
Write-Host '========================================' -ForegroundColor Cyan;
Write-Host '  Dev Environment Setup - Auto Launcher' -ForegroundColor Cyan;
Write-Host '========================================' -ForegroundColor Cyan;
Write-Host '';

Write-Log 'Waiting for internet connection...';
while (-not (Test-Connection -ComputerName 1.1.1.1 -Count 1 -Quiet)) {
    Write-Host ' -> No internet connection. Please connect to a network and wait...' -ForegroundColor Yellow;
    Write-Log 'No internet. Waiting 10 seconds...';
    Start-Sleep -Seconds 10;
}
Write-Log 'Internet connection established.';

if (Test-Path $extractDir) {
    Remove-Item -LiteralPath $extractDir -Recurse -Force;
}

Write-Log "Downloading repository from $repoUrl...";
try {
    Invoke-WebRequest -Uri $repoUrl -OutFile $zipPath -UseBasicParsing;
}
catch {
    Write-Host "[ERROR] Failed to download repository: $_" -ForegroundColor Red;
    Write-Log "Download failed: $_";
    exit 1;
}

Write-Log 'Extracting archive...';
Expand-Archive -Path $zipPath -DestinationPath $extractDir -Force;

$repoRoot = Get-ChildItem -LiteralPath $extractDir -Directory | Select-Object -First 1;
$setupScript = Join-Path $repoRoot.FullName 'setup\setup.ps1';

if (-not (Test-Path $setupScript)) {
    Write-Host "[ERROR] setup.ps1 not found in downloaded archive at $setupScript" -ForegroundColor Red;
    Write-Log "setup.ps1 not found at $setupScript";
    exit 1;
}

Write-Log "Found setup.ps1 at $setupScript";

$currentIdentity = [Security.Principal.WindowsIdentity]::GetCurrent();
$windowsPrincipal = New-Object Security.Principal.WindowsPrincipal($currentIdentity);
$isAdmin = $windowsPrincipal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator);

if (-not $isAdmin) {
    Write-Host 'Relaunching as Administrator...' -ForegroundColor Yellow;
    Write-Log 'Current process is not elevated. Relaunching as Administrator...';
    $arguments = '-NoProfile -ExecutionPolicy Bypass -File "' + $setupScript + '"';
    Start-Process -FilePath 'powershell.exe' -Verb RunAs -ArgumentList $arguments -WorkingDirectory (Split-Path -Parent $setupScript);
    exit 0;
}

Write-Log 'Already running as Administrator. Executing setup.ps1...';
& $setupScript;
